import React from "react";
import { Sequence, staticFile, interpolate, useVideoConfig } from "remotion";
import { Audio } from "@remotion/media";
import type { Caption } from "@remotion/captions";

// Sound-design helpers. Library files are generated by `npm run audio`
// (scripts/synth-audio.mjs) into public/audio/lib/{sfx,amb,music}.

export type SfxName =
  | "whoosh" | "whoosh_fast" | "whoosh_soft" | "swish" | "pop" | "pop_high" | "boing"
  | "impact" | "impact2" | "braam" | "riser" | "swell" | "tick" | "tock" | "page_flip" | "page_flip2"
  | "paper" | "thud" | "stamp" | "ding" | "sting" | "whack" | "explosion" | "gunshot" | "clang"
  | "footstep" | "footstep2" | "footstep3" | "footstep4" | "heartbeat" | "scribble" | "camera_flash";
export type AmbName = "room_tone" | "clock" | "waves" | "jungle_night" | "fire" | "wind" | "rain" | "battle_distant";
export type MusicName = "tension" | "curious" | "somber" | "epic";

export const sfxSrc = (n: SfxName) => staticFile(`audio/lib/sfx/${n}.wav`);
export const ambSrc = (n: AmbName) => staticFile(`audio/lib/amb/${n}.wav`);
export const musicSrc = (n: MusicName) => staticFile(`audio/lib/music/${n}.wav`);

const sec = (s: number, fps: number) => Math.round(s * fps);

/** One-shot sound effect at `at` seconds on the current timeline. */
export const Sfx: React.FC<{ name: SfxName; at: number; volume?: number; rate?: number; duck?: (frame: number) => number }> = ({
  name,
  at,
  volume = 0.7,
  rate = 1,
  duck,
}) => <SoundAt src={sfxSrc(name)} at={at} volume={volume} rate={rate} duck={duck} name={`sfx:${name}`} />;

/** Looping bed between `from` and `to` seconds with fades. */
export const Bed: React.FC<{
  src: string;
  from: number;
  to: number;
  volume?: number;
  fadeIn?: number;
  fadeOut?: number;
  /** Extra per-frame gain multiplier (absolute timeline frame). */
  gainAt?: (frame: number) => number;
  name?: string;
}> = ({ src, from, to, volume = 0.5, fadeIn = 0.4, fadeOut = 0.6, gainAt, name }) => {
  const { fps } = useVideoConfig();
  const start = sec(from, fps);
  const len = Math.max(1, sec(to - from, fps));
  return (
    <Sequence from={start} durationInFrames={len} layout="none" name={name ?? "bed"}>
      <Audio
        src={src}
        loop
        loopVolumeCurveBehavior="extend"
        volume={(f) => {
          const fi = fadeIn > 0 ? interpolate(f, [0, fadeIn * fps], [0, 1], { extrapolateRight: "clamp" }) : 1;
          const fo = fadeOut > 0 ? interpolate(f, [len - fadeOut * fps, len], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) : 1;
          return volume * fi * fo * (gainAt ? gainAt(start + f) : 1);
        }}
      />
    </Sequence>
  );
};

export const Ambience: React.FC<{
  name: AmbName;
  from: number;
  to: number;
  volume?: number;
  fadeIn?: number;
  fadeOut?: number;
  gainAt?: (frame: number) => number;
}> = ({
  name,
  ...rest
}) => <Bed src={ambSrc(name)} name={`amb:${name}`} {...rest} />;

/**
 * Sidechain-style ducking curve from voiceover word timings: returns 1 when
 * nobody speaks and `depth` while the voice is active (smooth 150 ms ramps).
 */
export const duckFromCaptions = (captions: Caption[], fps: number, depth = 0.45, ramp = 0.15) => {
  const spans = captions.map((c) => [c.startMs / 1000 - 0.08, c.endMs / 1000 + 0.2] as const);
  const curve = (t: number) => {
    let d = Infinity;
    for (const [a, b] of spans) {
      if (t >= a && t <= b) return depth;
      d = Math.min(d, t < a ? a - t : t - b);
    }
    const k = Math.min(1, d / ramp);
    return depth + (1 - depth) * k;
  };
  // every audio element asks for its gain on every frame: cache per frame
  const cache = new Map<number, number>();
  return (frame: number) => {
    let v = cache.get(frame);
    if (v === undefined) {
      v = curve(frame / fps);
      cache.set(frame, v);
    }
    return v;
  };
};

/** Music bed. Ducks under the voiceover when `duck` is given. */
export const Music: React.FC<{
  name: MusicName;
  from: number;
  to: number;
  volume?: number;
  fadeIn?: number;
  fadeOut?: number;
  duck?: (frame: number) => number;
  /** Additional automation (e.g. drop out for a dramatic beat). */
  automation?: (frame: number) => number;
}> = ({ name, duck, automation, ...rest }) => (
  <Bed
    src={musicSrc(name)}
    name={`music:${name}`}
    gainAt={(f) => (duck ? duck(f) : 1) * (automation ? automation(f) : 1)}
    {...rest}
  />
);

/** Licensed bundle file imported with scripts/import-sfx.mjs (gitignored). */
export const licensedSrc = (bundle: string, name: string, ext = "mp3") => staticFile(`audio/licensed/${bundle}/${name}.${ext}`);

/**
 * Any one-shot audio file at `at` seconds. `duck` (absolute frame → gain)
 * pulls it under the voiceover while someone is speaking.
 */
export const SoundAt: React.FC<{
  src: string;
  at: number;
  volume?: number;
  rate?: number;
  name?: string;
  duck?: (frame: number) => number;
  /** Seconds to keep the sound mounted (≥ the file's length); unmounting afterwards keeps long renders fast. */
  dur?: number;
}> = ({ src, at, volume = 0.7, rate = 1, name, duck, dur = 8 }) => {
  const { fps } = useVideoConfig();
  const from = Math.max(0, sec(at, fps));
  return (
    <Sequence from={from} durationInFrames={Math.ceil((dur * fps) / rate)} layout="none" name={name ?? "sfx"}>
      <Audio src={src} volume={duck ? (f) => volume * duck(from + f) : volume} playbackRate={rate} />
    </Sequence>
  );
};
